const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function connectPublicAI(client){const status=await client.status();if(!status.publicAccess)throw Error('当前地址未启用公开 AI 服务');if(!status.configured)throw Error('网站 AI 服务尚未完成模型配置');client.publicAccess=true;const session=await client.request('/api/public/session',{});client.token=session.token;client.pacer.perMinute=session.limits?.requestsPerMinute||20;client.accessMode='visitor';return {status,session};}
export function openPublicAIInfo({modal,config,client,reconnect,mode,changeMode,onAnalyze,onAccessChange=()=>{}}){
 const d=modal('<div id="public-info"><p>正在获取服务状态…</p></div>','网站 AI · 访问模式与用量');const body=d.querySelector('#public-info');let closed=false;d.addEventListener('close',()=>closed=true,{once:true});
 async function show(){try{if(!config.active)throw Error(config.note||'公开 AI 尚未上线');let api=client();if(!api.publicAccess||!api.token){await reconnect();api=client();}const info=await api.request('/api/public/usage');if(closed)return;const authorized=info.accessMode==='authorized';api.accessMode=info.accessMode;onAccessChange();
 body.innerHTML=`<div class="setup-success"><b>网站 AI 已连接 · ${authorized?'授权模式':'普通访客'}</b><p>普通访客无需密码，无需个人 API Key。评论判别与证据整理关闭思考，最终宣传方案开启思考。只有分析、整理证据和生成方案才调用模型。</p></div><div class="kpis">${[['本次已提交评论',info.used.comments,info.limits.comments],['本次已生成方案',info.used.plans,info.limits.plans],['本次已请求摘要',info.used.summaries,info.limits.summaries]].map(([l,n,m])=>`<div class="kpi"><span>${l}</span><strong>${n}<small> / ${m===null?'不限访客额度':m}</small></strong></div>`).join('')}</div>
 <div class="notice">${authorized?'已解除本次会话的评论、方案、摘要及同网络每日体验额度。':'普通访客：每个会话最多 '+info.limits.comments+' 条评论、'+info.limits.plans+' 份方案；同一网络每日最多 '+info.limits.commentsPerNetworkDay+' 条评论、'+info.limits.plansPerNetworkDay+' 份方案。'}两种模式均保留同一网络每分钟 ${info.limits.requestsPerMinute} 次操作、全站并发 ${info.limits.concurrency} 个请求、全站每日 ${info.dailyCalls} 次模型调用及 ${info.dailyTokens.toLocaleString()} tokens 保守上限。</div>
 ${authorized?'<button id="public-lock">退出授权模式</button>':`<section class="panel"><h4>有访问密码？进入授权模式</h4><p>后台验证密码；授权只在当前访客会话有效，不是管理员权限。</p>${info.authorizationAvailable?'<form id="public-unlock"><label>访问密码<input name="password" type="password" autocomplete="off" minlength="6" maxlength="128" required></label><button class="primary">验证并进入授权模式</button><p id="unlock-result" role="status"></p></form>':'<p>所有者尚未启用授权密码，普通访客仍可使用 AI。</p>'}</section>`}
 <p class="muted">会话在 ${esc(new Date(info.expiresAt).toLocaleString())} 到期；刷新、会话过期或更换网络后可能需要重新授权。密码不保存到浏览器工作空间。授权不取消供应商限流、余额要求和全站费用保护。同一 Wi-Fi 访客共用网络频率限制，失败请求可能计入额度。用量按北京时间重置，不等于供应商账单。</p>
 <label>分析方式<select id="public-mode"><option value="ai" ${mode()==='ai'?'selected':''}>真实 AI（网站提供）</option><option value="rules" ${mode()==='rules'?'selected':''}>规则与模板演示（不调用模型）</option></select></label><div class="toolbar"><button id="public-start" class="primary">开始分析评论 →</button><button id="public-refresh">刷新用量</button></div><p class="muted">连接成功仅表示后台与访客会话可用，不代表模型输出已经验证；原文证据仍需人工复核。</p>`;
 body.querySelector('#public-mode').onchange=async e=>changeMode(e.target.value);body.querySelector('#public-start').onclick=()=>{d.close();onAnalyze();};body.querySelector('#public-refresh').onclick=show;
 const unlock=body.querySelector('#public-unlock');if(unlock)unlock.onsubmit=async e=>{e.preventDefault();const input=unlock.elements.password,button=unlock.querySelector('button');button.disabled=true;try{const pending=api.request('/api/public/authorize',{password:input.value});input.value='';await pending;await show();}catch(e){if(!closed){unlock.querySelector('#unlock-result').textContent=e.message;button.disabled=false;}}};
 const lock=body.querySelector('#public-lock');if(lock)lock.onclick=async()=>{lock.disabled=true;try{await api.request('/api/public/deauthorize',{});await show();}catch(e){lock.disabled=false;lock.textContent=e.message;}};
 }catch(e){if(closed)return;body.innerHTML=`<div class="notice error"><b>AI 暂时没有连接成功</b><p>${esc(e.message)}</p></div><p>原有数据和规则演示仍可使用，不会用模拟结果冒充 AI。</p><button id="public-retry" class="primary">重新连接</button>`;body.querySelector('#public-retry').onclick=async()=>{try{await reconnect();await show();}catch(e){body.querySelector('.notice p').textContent=e.message;}};}}
 show();return d;
}
